What would you do with the slice of orders? One approach is to
@memset(orders, undefined)
and hand the slice over to a pool which tracks spare objects with a bit set:

const OrderPool = struct {
    orders: []Order,
    free: DynamicBitSet,

    fn acquire(pool: *OrderPool) ?*Order { ... }
    fn release(pool: *OrderPool, order: *Order) { ... }
};

const OrderPool = struct {
    orders: []union {
        order: Order,
        next_free: ?u32,
    },
    first_free: ?u32,
};

const Order = {
    id: u128,
    price: u32,
    count: u32,

    tag: enum { bid, ask, reserved },

    pub const reserved: Order = .{
        .id = 0,
        .price = 0,
        .count = 0,
        .tag = .reserved,
    };
};

for (orders) |order| {
    process(order)
}

for (orders_active) |order_index| {
    const order = orders[order_index];
    process(order);
}

const item = for (items) |item| {
    if (predicate(item)) break item;
} else null;

